:root {
  --radius: 0.5rem;

  /* === KURSVERWALTUNG DESIGN SYSTEM === */
  /* Font */
  --font-sans: 'IBM Plex Sans', sans-serif;
  --font-mono: 'IBM Plex Mono', monospace;

  /* Core palette — deep indigo + warm cream */
  --background: oklch(0.978 0.004 264);
  --foreground: oklch(0.18 0.03 264);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.18 0.03 264);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.18 0.03 264);

  /* Primary: deep indigo */
  --primary: oklch(0.38 0.16 264);
  --primary-foreground: oklch(0.98 0 0);

  /* Secondary: soft slate */
  --secondary: oklch(0.94 0.006 264);
  --secondary-foreground: oklch(0.38 0.16 264);

  /* Muted */
  --muted: oklch(0.955 0.005 264);
  --muted-foreground: oklch(0.52 0.04 264);

  /* Accent: warm amber */
  --accent: oklch(0.92 0.08 75);
  --accent-foreground: oklch(0.35 0.12 60);

  --destructive: oklch(0.577 0.245 27.325);
  --border: oklch(0.9 0.008 264);
  --input: oklch(0.93 0.006 264);
  --ring: oklch(0.38 0.16 264 / 0.4);

  /* Charts */
  --chart-1: oklch(0.38 0.16 264);
  --chart-2: oklch(0.72 0.14 75);
  --chart-3: oklch(0.55 0.14 160);
  --chart-4: oklch(0.62 0.18 20);
  --chart-5: oklch(0.58 0.15 310);

  /* Sidebar — deep indigo dark panel */
  --sidebar: oklch(0.22 0.06 264);
  --sidebar-foreground: oklch(0.88 0.02 264);
  --sidebar-primary: oklch(0.72 0.14 75);
  --sidebar-primary-foreground: oklch(0.18 0.04 60);
  --sidebar-accent: oklch(0.30 0.07 264);
  --sidebar-accent-foreground: oklch(0.92 0.02 264);
  --sidebar-border: oklch(0.30 0.06 264);
  --sidebar-ring: oklch(0.72 0.14 75);

  /* Custom tokens */
  --gradient-hero: linear-gradient(135deg, oklch(0.38 0.16 264), oklch(0.28 0.12 280));
  --gradient-amber: linear-gradient(135deg, oklch(0.78 0.16 75), oklch(0.72 0.18 60));
  --gradient-subtle: linear-gradient(160deg, oklch(0.978 0.004 264), oklch(0.96 0.01 264));
  --shadow-card: 0 1px 3px oklch(0.18 0.03 264 / 0.08), 0 4px 12px oklch(0.18 0.03 264 / 0.06);
  --shadow-hero: 0 8px 30px -8px oklch(0.38 0.16 264 / 0.35);
  --transition-smooth: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);

  /* Status colors */
  --status-geplant: oklch(0.62 0.12 220);
  --status-aktiv: oklch(0.55 0.16 160);
  --status-abgeschlossen: oklch(0.52 0.04 264);
  --status-abgesagt: oklch(0.577 0.245 27.325);
}

